import java.io.*
import java.util.*

fun isLucky(x: Long): Boolean {
    if (x <= 0) return false
    var v = x
    while (v > 0) {
        val d = v % 10
        if (d != 4L && d != 7L) return false
        v /= 10
    }
    return true
}

fun countLucky(x: Long): Int {
    if (x < 4) return 0
    var cnt = 0
    val queue: ArrayDeque<Long> = ArrayDeque()
    queue.add(4L)
    queue.add(7L)
    while (queue.isNotEmpty()) {
        val cur = queue.poll()
        if (cur <= x) {
            cnt++
            if (cur <= 2_000_000_000L) {
                queue.add(cur * 10 + 4)
                queue.add(cur * 10 + 7)
            }
        }
    }
    return cnt
}

fun main() {
    val st = StringTokenizer(BufferedReader(InputStreamReader(System.`in`)).readLine())
    val n = st.nextToken().toLong()
    val k = st.nextToken().toLong()

    val f = LongArray(21)
    f[0] = 1
    for (i in 1..20) f[i] = f[i - 1] * i

    var m = -1
    for (i in 0..20) {
        if (f[i] >= k) { m = i; break }
    }
    if (m == -1 || m.toLong() > n) {
        println(-1)
        return
    }

    val nums = ArrayList<Long>()
    for (i in (n - m + 1)..n) nums.add(i)

    var rem = k - 1
    val perm = ArrayList<Long>()
    for (i in m downTo 1) {
        val block = f[i - 1]
        val idx = (rem / block).toInt()
        rem %= block
        perm.add(nums[idx])
        nums.removeAt(idx)
    }

    var ans = countLucky(n - m)
    for (j in 0 until m) {
        val pos = n - m + j + 1
        val v = perm[j]
        if (isLucky(pos) && isLucky(v)) ans++
    }
    println(ans)
}
